\title{The Combinatorics of Universal Information Spaces:\\
Counting, Probability, and Cataloging in the Library of Babel}
\author{Aristotle}
\date{June 20, 2026}

\begin{document}
\begin{abstract}
We give a self-contained combinatorial analysis of Jorge Luis Borges' \emph{Library of Babel}
and the broader class of \emph{universal information spaces}: the set of all strings of a fixed
length over a fixed finite alphabet. We establish four groups of verified results. First, an
\textbf{enumeration} layer: the space of length-$L$ volumes over a $b$-symbol alphabet has
exactly $b^L$ elements and admits an explicit order-isomorphism (the \emph{universal catalog})
with $\{0,\ldots,b^L-1\}$. Second, a \textbf{probabilistic} layer: under the uniform
distribution, a fixed target volume has probability $b^{-L}$, the expected number of
occurrences of a length-$k$ pattern is exactly $(L-k+1)\,b^{-k}$, and the probability a random
volume contains it is at most $(L-k+1)\,b^{-k}$. Third, a \textbf{constructive cataloging}
result: for the mini-library with alphabet size $4$ and address length $2$, a single volume of
optimal length $16$ --- an explicit de Bruijn word $B(4,2)$ --- catalogs all $16$ addresses
exactly once, formalized as a bijection between cyclic window positions and the address space.
Fourth, an \textbf{impossibility/threshold} result: no single volume can injectively encode all
sub-collections of the library (Cantor diagonal, $2^{(b^L)}>b^L$), while a distributed catalog
across $N$ volumes can do so \emph{iff} $2^{(b^L)}\le (b^L)^N$, equivalently
$N\ge b^L/(L\log_2 b)$.
\end{abstract}

\maketitle

\section{Introduction}
Borges' 1941 story posits a library of all books of a fixed length over a fixed alphabet. Two
questions animate it: how vast is the collection, and can one find meaning---or a guide to
meaning---within it? These are mathematical questions, made concrete by modern information
spaces (all files of a given size). We model the library as the finite type of all strings of
length $L$ over an alphabet of size $b$ and answer the counting, probability, and cataloging
questions exactly. The work bridges finite combinatorics (counting, de Bruijn sequences),
probability (uniform string models), and set theory / information theory (Cantor
diagonalization, encoding capacity).

\section{Definitions}
Throughout, $b,L,n,k,N$ denote natural numbers.

\begin{definition}[Alphabet and volume]
The alphabet is $\Fin\,b=\{0,\ldots,b-1\}$. A \emph{volume} of length $L$ is a function
$v:\Fin\,L\to\Fin\,b$. We write $\Volume(b,L)$ for the type of such volumes. Borges'
specialization is $b=25$, $L=1{,}312{,}000$.
\end{definition}

\begin{definition}[Library and uniform probability]
The \emph{library} $\Library(b,L)$ is the full finite type $\Volume(b,L)$. For a subset $S$,
the counting probability is $\Pr(S)=|S|/|\Volume(b,L)|$.
\end{definition}

\begin{definition}[de Bruijn catalog volume]
For $b=4$, the catalog volume is the length-$16$ word
$\cat=(0,0,1,0,2,0,3,1,1,2,1,3,2,2,3,3)$, viewed as $\cat:\Fin\,16\to\Fin\,4$.
\end{definition}

\begin{definition}[Window map]
The window at cyclic position $i\in\Fin\,16$ is
$\window(i)=(\cat(i),\cat(i+1))\in\Fin\,4\times\Fin\,4$, with $i+1$ taken modulo $16$.
\end{definition}

\begin{definition}[Pattern occurrence]
A pattern of length $k$ is $p:\Fin\,k\to\Fin\,b$. It occurs at position $i$ in a length-$L$
volume $v$ if $v(i+j)=p(j)$ for all $j<k$ (with $i+k\le L$); $v$ \emph{contains} $p$ if it
occurs at some position. The occurrence count is the number of such positions.
\end{definition}

\section{Enumeration}
\begin{theorem}[Cardinality of the library]
For all $b,L$, $\ |\Volume(b,L)|=b^L$. In particular $|\Volume(25,1312000)|=25^{1312000}$.
\end{theorem}
\begin{proof}[Proof sketch]
A volume is a function from the $L$-element index type into the $b$-element alphabet; the number
of such functions is $b^L$.
\end{proof}

\begin{theorem}[Universal catalog]
There is an explicit bijection $\mathrm{universalCatalog}:\Volume(b,L)\leftrightarrow\Fin(b^L)$
with verified encode/decode correctness.
\end{theorem}
\begin{proof}[Proof sketch]
Read a volume as a base-$b$ numeral, $a=\sum_i v(i)b^i$; this mixed-radix correspondence is a
bijection whose two round-trip identities follow from digit recovery.
\end{proof}

\section{Probability}
\begin{theorem}[Single-target probability]
For any fixed $v\in\Volume(b,L)$, $\ \Pr(\{v\})=b^{-L}$.
\end{theorem}
\begin{proof}[Proof sketch]
A singleton has cardinality $1$; divide by $|\Volume(b,L)|=b^L$ from Theorem~1.
\end{proof}

\begin{theorem}[Expected substring count]
For $k\le L$, $b>0$, and a length-$k$ pattern $p$, the expected number of occurrences of $p$ in
a uniformly random length-$L$ volume is exactly $(L-k+1)\,b^{-k}$.
\end{theorem}
\begin{proof}[Proof sketch]
By linearity over the $L-k+1$ start positions. At a fixed position the match constrains exactly
$k$ of the $L$ symbols, so $b^{L-k}$ volumes match, giving per-position probability $b^{-k}$;
sum over $L-k+1$ positions.
\end{proof}

\begin{theorem}[Containment union bound]
Under the same hypotheses,
$\ \Pr(\{v: v\text{ contains }p\})\le (L-k+1)\,b^{-k}$.
\end{theorem}
\begin{proof}[Proof sketch]
The containment event is the union over start positions of per-position match events; bound the
union's cardinality by the sum, then divide by $b^L$. Each term is $b^{L-k}/b^L=b^{-k}$, with
$L-k+1$ terms.
\end{proof}

\begin{remark}
Theorems~4--5 make precise the heuristic that locating a passage $T$ of complexity $k$ has
probability $\approx|T|\cdot b^{-k}$: the $b^{-k}$ factor is the exponential cost per demanded
symbol; the $(L-k+1)\approx L$ factor is the linear gain from many trial positions.
\end{remark}

\section{Constructive Cataloging: the de Bruijn Mini-Catalog}
Take $b=4$, address length $n=2$, with $4^2=16$ addresses.

\begin{theorem}[Window bijection]
The window map $\window:\Fin\,16\to\Fin\,4\times\Fin\,4$ of Definition~4 is a bijection.
\end{theorem}
\begin{proof}[Proof sketch]
Both source and target have cardinality $16$. By the principle ``$f$ is bijective iff injective
and the cardinalities match,'' it suffices to verify injectivity of the explicit $16$-entry map,
a finite decidable check; combined with $|\Fin\,16|=|\Fin\,4\times\Fin\,4|$ this gives
bijectivity.
\end{proof}

\begin{corollary}[Every address exactly once]
For every address $p$ there is a unique cyclic position $i$ with $\window(i)=p$.
\end{corollary}

\begin{corollary}[Completeness]
Every address occurs: $\forall p,\ \exists i,\ \window(i)=p$.
\end{corollary}

\begin{corollary}[Optimality / no repeats]
$\window$ is injective; since the volume has length $16=4^2$, this is the minimum possible length
for a single window-complete volume.
\end{corollary}

\begin{remark}
A single volume listing every length-$n$ address exactly once is precisely a de Bruijn sequence
$B(b,n)$, equivalently an Eulerian circuit in the de Bruijn graph on $b^{n-1}$ nodes with $b^n$
edges. We supply an explicit witness rather than a general existence theorem.
\end{remark}

\section{Diagonal Impossibility and the Distributed Threshold}
We sharpen ``catalog the whole library'' to ``injectively encode every sub-collection,'' of
which there are $2^{(b^L)}$.

\begin{theorem}[No single complete catalog]
For all $b,L$, there is no injection from $\mathrm{Finset}(\Volume(b,L))$ into a single
$\Volume(b,L)$; equivalently $b^L<2^{(b^L)}$.
\end{theorem}
\begin{proof}[Proof sketch]
A single volume realizes one of $b^L$ values; the sub-collections number $2^{(b^L)}$. Since
$m<2^m$ for every natural $m$, no injection exists. This holds unconditionally, including
$b\in\{0,1\}$.
\end{proof}

\begin{theorem}[Distributed catalog threshold]
A distributed catalog across $N$ volumes --- an injection
$\mathrm{Finset}(\Volume(b,L))\hookrightarrow(\Fin\,N\to\Volume(b,L))$ --- exists if and only if
$\ 2^{(b^L)}\le (b^L)^N$.
\end{theorem}
\begin{proof}[Proof sketch]
The codomain has cardinality $(b^L)^N$, the domain $2^{(b^L)}$. Between finite types an injection
exists iff the domain cardinality does not exceed the codomain's.
\end{proof}

\begin{corollary}[Single volume below threshold]
The $N=1$ instance never holds: $2^{(b^L)}\le b^L$ is false for all $b,L$, recovering Theorem~10.
\end{corollary}

Taking $\log_b$ of $(b^L)^N=b^{LN}$ and of $2^{(b^L)}=b^{(b^L)\log_b 2}$, the condition becomes
$N L\ge b^L\log_b 2$, i.e.
\[
N\ \ge\ \frac{b^L}{L\,\log_2 b}.
\]
For $b=25$, $L=1{,}312{,}000$, a complete sub-collection index requires
$N\ge 25^{1312000}/(1312000\cdot\log_2 25)$ volumes.

\section{Algorithms}
\textbf{(A) de Bruijn catalog construction.} Form the de Bruijn graph on $b^{n-1}$ nodes with one
edge per length-$n$ address; since in- and out-degree are $b$ everywhere, an Eulerian circuit
exists; traverse it (Hierholzer, $O(b^n)$) emitting one symbol per edge.

\textbf{(B) Distributed feasibility test.} Decide $2^{(b^L)}\le (b^L)^N$ via the overflow-safe
form $b^L\log 2\le N L\log b$; $O(1)$ on logarithms.

\textbf{(C) Universal catalog encode/decode.} Convert address $\leftrightarrow$ volume by base-$b$
expansion; $O(L)$ digit operations.

\section{Applications and Discussion}
The Library models any universal information space: all files of fixed size, images of fixed
resolution, genomes of fixed length. Generation is free; the catalog is the scarce resource.
Addresses are cheaply and optimally catalogable (Theorem~6); contents (the power set) are not
catalogable in any single artifact (Theorem~10) and cost a near-duplicate library to catalog at
all (Theorem~11). The probability layer (Theorem~5) explains search inside such a space.

\section{Future Work}
(FD-1) a polynomial-time constructive distributed encoder via base-$b$ bit-packing; (FD-2)
generality and counting of de Bruijn catalogs via Euler's theorem and the BEST theorem; (FD-3)
strict-majority incompressibility densities; (FD-4) the catalog-of-catalogs hierarchy and its
iterated-exponential storage growth.

\section{Conclusion}
The Library of Babel is finite ($b^L$), perfectly address-indexable, governed by the
meaning-finding probability $(L-k+1)b^{-k}$, and bounded by a Cantor wall for content-cataloging
that only a distributed catalog crossing $2^{(b^L)}\le (b^L)^N$ can scale. In a universe where
every text exists, the map is the hardest thing to make.

\end{document}

