from fractions import Fraction
from itertools import product
from typing import Tuple

def prob_singleton(b: int, L: int) -> Fraction:
    return Fraction(1, b ** L)

def expected_occurrences(b: int, L: int, k: int) -> Fraction:
    return Fraction(0) if k > L else Fraction(L - k + 1, b ** k)

def empirical_containment(b: int, L: int, pattern: Tuple[int, ...]) -> Fraction:
    k = len(pattern); count = total = 0
    for v in product(range(b), repeat=L):
        total += 1
        if any(v[i:i+k] == pattern for i in range(L - k + 1)):
            count += 1
    return Fraction(count, total)

if __name__ == '__main__':
    b, L, pattern = 3, 6, (1, 2)
    bound = expected_occurrences(b, L, len(pattern))
    emp = empirical_containment(b, L, pattern)
    print('prob_singleton =', prob_singleton(b, L))
    print('expected count =', bound, float(bound))
    print('empirical P    =', emp, float(emp))
    print('bound holds:', emp <= bound)

from math import log, log2

def feasible_exact(b: int, L: int, N: int) -> bool:
    v = b ** L
    return (2 ** v) <= (v ** N)

def threshold(b: int, L: int) -> float:
    return (b ** L) / (L * log2(b))

if __name__ == '__main__':
    b, L = 2, 3
    v = b ** L
    print('b^L =', v, ' 2^(b^L) =', 2 ** v)
    print('no_single_complete_catalog:', v < 2 ** v)
    print('single_volume_below_threshold:', not feasible_exact(b, L, 1))
    smallest = next(N for N in range(1, 100) if feasible_exact(b, L, N))
    print('smallest feasible N =', smallest)
    print('threshold b^L/(L log2 b) =', round(threshold(b, L), 3))

