function DEBRUIJN(b, n):
  nodes <- all length-(n-1) strings over {0..b-1}
  edges <- all length-n strings (one per address)
  adj[v] <- ordered list of out-symbols for node v
  circuit <- empty stack; path <- []
  push start node (all zeros)
  while stack nonempty:
    v <- top of stack
    if adj[v] nonempty:
      s <- pop next symbol of adj[v]
      push successor node (v shifted with s)
    else:
      path.append(last symbol of pop(stack))
  return reverse(path)   # cyclic catalog word of length b^n

